import {
  Group, Mesh, PlaneGeometry, BoxGeometry, Vector3,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial
} from 'three/webgpu';
import {
  uniform, time, vec3, vec4, mix, smoothstep, uv, texture, positionWorld, normalWorld,
  mul, add, dot, max, abs, sin, cos, clamp, length, normalize, color as colorNode,
  modelViewMatrix, positionLocal, transformNormalToView, float, timerLocal
} from 'three/tsl';
import { gsap } from 'gsap';

const CARD_COUNT = 5;
const CARD_WIDTH = 1.6;
const CARD_HEIGHT = 1.0;
const CARD_PITCH = 1.85;
const BEVEL = 0.025;
const STRIP_Y_ROT = -18 * Math.PI / 180;

const CAPTIONS = [
  'NA-01 MERIDIAN',
  'NA-02 NOCTURNE',
  'NA-03 SIGNAL',
  'NA-04 VANTAGE',
  'NA-05 ARCHIVE'
];

const IMAGE_VARIANTS = [
  '/prism-mock/home/nodes/parallax-stack.png',
  '/prism-mock/home/nodes/parallax-stack-2.png',
  '/prism-mock/home/nodes/parallax-stack-3.png',
  '/prism-mock/home/nodes/parallax-stack-4.png',
  '/prism-mock/home/nodes/parallax-stack-5.png'
];

export default function createNode(config, ctx) {
  const group = new Group();
  const textures = [];
  const cards = [];
  const cardMatrices = [];
  const cleanupFns = [];

  // --- Load textures ---
  const loadPromises = IMAGE_VARIANTS.map((url, i) => {
    return ctx.textureLoader.loadTexture(url).then(tex => {
      textures[i] = tex;
      tex.wrapS = tex.wrapT = ctx.THREE.RepeatWrapping;
    });
  });

  // --- Create backdrop ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    side: ctx.THREE.DoubleSide,
    roughness: 0.8,
    metalness: 0.1
  });

  const gradientTop = colorNode('#0b0b10');
  const gradientBottom = colorNode('#12121a');
  const uvCoord = uv();
  const gradientMix = smoothstep(0.0, 1.0, uvCoord.y);
  const finalColor = mix(gradientBottom, gradientTop, gradientMix);
  backdropMat.colorNode = finalColor;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Headline ---
  const headlineConfig = config.textContent?.[0] || { text: 'The collection', typography: { fontSize: 68 } };
  const headline = ctx.fontAtlas.createText(headlineConfig.text, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  // --- Body ---
  const bodyConfig = config.textContent?.[1] || { text: 'Five calibres. One discipline.', typography: { fontSize: 26 } };
  const body = ctx.fontAtlas.createText(bodyConfig.text, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  group.add(body);

  // --- Create cards after textures load ---
  Promise.all(loadPromises).then(() => {
    const stripGroup = new Group();

    for (let i = 0; i < CARD_COUNT; i++) {
      const isFocused = i === 2; // Center card
      const xOffset = (i - 2) * CARD_PITCH;

      // Card plate
      const plateGeo = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
      const plateMat = new MeshStandardNodeMaterial({
        roughness: 0.55,
        metalness: 0.2,
        clearcoat: 0.15,
        side: ctx.THREE.DoubleSide
      });

      if (textures[i]) {
        const texNode = texture(textures[i]);
        // Parallax UV offset for scroll
        const scrollOffset = uniform(0);
        const parallaxUv = uv().add(vec3(mul(scrollOffset, float(0.04)), 0, 0).xy);
        plateMat.map = textures[i];
        plateMat.colorNode = texNode;
        plateMat.needsUpdate = true;
      }

      const plate = new Mesh(plateGeo, plateMat);
      plate.position.x = xOffset;

      // Bevel frame
      const bevelGeo = new PlaneGeometry(CARD_WIDTH + BEVEL * 2, CARD_HEIGHT + BEVEL * 2);
      const bevelMat = new MeshStandardNodeMaterial({
        color: '#16161d',
        roughness: 0.6,
        metalness: 0.3,
        side: ctx.THREE.DoubleSide
      });
      const bevel = new Mesh(bevelGeo, bevelMat);
      bevel.position.z = -0.01;

      const cardGroup = new Group();
      cardGroup.add(bevel);
      cardGroup.add(plate);
      cardGroup.position.x = xOffset;

      // Focused card counter-rotation
      if (isFocused) {
        cardGroup.rotation.y = -STRIP_Y_ROT;
        cardGroup.scale.set(1, 1, 1);

        // Underline bar
        const barGeo = new PlaneGeometry(CARD_WIDTH, 0.035);
        const barMat = new MeshBasicNodeMaterial({
          color: '#ff2a38'
        });
        const bar = new Mesh(barGeo, barMat);
        bar.position.y = -0.55;
        bar.position.z = 0.02;
        cardGroup.add(bar);

        // Caption
        const caption = ctx.fontAtlas.createText(CAPTIONS[i], {
          fontSize: 18,
          color: '#ff2a38',
          align: 'center',
          fontWeight: '700',
          letterSpacing: 0.08 * 18
        });
        caption.position.set(0, -0.65, 0.02);
        caption.scale.set(0.005, 0.005, 0.005);
        cardGroup.add(caption);
      } else {
        cardGroup.scale.set(0.92, 0.92, 0.92);
        const distance = Math.abs(i - 2);
        const opacity = 1.0 - (distance * 0.22);
        plateMat.opacity = Math.max(0.55, opacity);
        plateMat.transparent = true;
        bevelMat.opacity = Math.max(0.55, opacity);
        bevelMat.transparent = true;

        // Caption for non-focused
        const caption = ctx.fontAtlas.createText(CAPTIONS[i], {
          fontSize: 18,
          color: '#e8ecf2',
          align: 'center',
          fontWeight: '700',
          letterSpacing: 0.08 * 18
        });
        caption.position.set(0, -0.65, 0.02);
        caption.scale.set(0.004, 0.004, 0.004);
        cardGroup.add(caption);
      }

      stripGroup.add(cardGroup);
      cards.push({
        group: cardGroup,
        plate,
        bevel,
        isFocused,
        originalX: xOffset,
        scrollOffset: uniform(0),
        plateMat
      });
    }

    stripGroup.rotation.y = STRIP_Y_ROT;
    group.add(stripGroup);

    // --- Parallax scroll primitive ---
    const primitiveResult = ctx.primitives['parallax-scroll'](stripGroup, {
      intensity: 0.5,
      cards: cards.map(c => ({
        element: c.group,
        offset: c.scrollOffset
      }))
    });

    if (primitiveResult) {
      if (primitiveResult.timeline) cleanupFns.push(() => primitiveResult.timeline.kill());
      if (primitiveResult.cleanup) cleanupFns.push(primitiveResult.cleanup);
    }

    // --- Snap-to-card on scroll end ---
    let snapTimeline = null;
    const snapToCard = (targetIndex) => {
      if (snapTimeline) snapTimeline.kill();
      const targetX = (targetIndex - 2) * CARD_PITCH * -1 * Math.sin(STRIP_Y_ROT);
      snapTimeline = gsap.timeline();
      snapTimeline.to(stripGroup.position, {
        x: targetX,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overshoot: 0.04,
        onComplete: () => {
          // Focus animation
          cards.forEach((card, i) => {
            if (i === targetIndex) {
              gsap.to(card.group.scale, {
                x: 1, y: 1, z: 1,
                duration: 0.6,
                ease: 'power4.out'
              });
              gsap.to(card.group.rotation, {
                y: -STRIP_Y_ROT,
                duration: 0.6,
                ease: 'power4.out'
              });
            } else {
              gsap.to(card.group.scale, {
                x: 0.92, y: 0.92, z: 0.92,
                duration: 0.6,
                ease: 'power4.out'
              });
              gsap.to(card.group.rotation, {
                y: 0,
                duration: 0.6,
                ease: 'power4.out'
              });
            }
          });
        }
      });
      cleanupFns.push(() => { if (snapTimeline) snapTimeline.kill(); });
    };

    // Initial state with focused center card
    setTimeout(() => snapToCard(2), 100);

    // Store for cleanup
    group.userData.snapToCard = snapToCard;
  });

  // --- Event handlers ---
  group.userData.handlers = {
    scroll: (event) => {
      const delta = event.deltaY || event.detail?.deltaY || 0;
      // Simple scroll to snap logic
      const scrollAmount = delta * 0.001;
      const snapIndex = Math.round(2 + scrollAmount);
      const clampedIndex = Math.max(0, Math.min(CARD_COUNT - 1, snapIndex));
      if (group.userData.snapToCard) {
        group.userData.snapToCard(clampedIndex);
      }
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    cleanupFns.forEach(fn => {
      if (typeof fn === 'function') fn();
    });

    // Dispose materials and geometries
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });

    // Dispose text
    [headline, body].forEach(text => {
      if (text && text.parent) {
        text.parent.remove(text);
        text.traverse((child) => {
          if (child.isMesh) {
            child.geometry?.dispose();
            child.material?.dispose();
          }
        });
      }
    });
  };

  return group;
}
